BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_model_cost_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,agent_run_id UUID REFERENCES mission_bridge_agent_runs(id),model TEXT NOT NULL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,estimated_cost_usd NUMERIC(12,6) NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_operational_alerts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,alert_type TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('info','warning','critical')),summary TEXT NOT NULL,trace_id TEXT,status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),acknowledged_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS mission_bridge_backup_drills(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),environment TEXT NOT NULL,backup_reference TEXT NOT NULL,restore_started_at TIMESTAMPTZ NOT NULL,restore_completed_at TIMESTAMPTZ,integrity_verified BOOLEAN NOT NULL DEFAULT FALSE,notes TEXT NOT NULL DEFAULT '');
ALTER TABLE mission_bridge_model_cost_events ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_model_cost_events USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));ALTER TABLE mission_bridge_operational_alerts ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_operational_alerts USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
COMMIT;
